import { ImageOff } from "lucide-react";

// Project photos live in /public/images as <name>-{640,1280,1920}.webp with a
// 1280 JPEG fallback (generated by scripts/optimize_images.py).
export type ProjectPhoto =
  | "nursing-training"
  | "patient-monitor"
  | "anatomy-models-wide"
  | "anatomy-models-tall"
  | "stethoscope-notebook";

export function Photo({
  name,
  alt,
  sizes = "100vw",
  priority = false,
  className,
}: {
  name: ProjectPhoto;
  alt: string;
  sizes?: string;
  priority?: boolean;
  className?: string;
}) {
  const base = `/images/${name}`;
  return (
    <picture className={className}>
      <source type="image/webp" srcSet={`${base}-640.webp 640w, ${base}-1280.webp 1280w, ${base}-1920.webp 1920w`} sizes={sizes} />
      <img
        src={`${base}-1280.jpg`}
        alt={alt}
        loading={priority ? "eager" : "lazy"}
        fetchPriority={priority ? "high" : "auto"}
        decoding="async"
      />
    </picture>
  );
}

/** Image from content data (a URL), or a clearly-labelled placeholder when missing. */
export function ContentImage({ src, alt, placeholder }: { src: string | null; alt: string; placeholder: string }) {
  if (!src) {
    return (
      <div className="media-placeholder">
        <ImageOff aria-hidden="true" />
        <span>{placeholder}</span>
      </div>
    );
  }
  return <img src={src} alt={alt} loading="lazy" decoding="async" />;
}
